/**
 * IPNetDB loader (src/shadow/ipnetdb.ts) with a fake fetch serving a manifest
 * and a database generated by test/helpers/mmdb-writer.ts (documentation
 * ranges only): first load, verification failures that keep the copy in use,
 * the host check, the weekly/Monday refresh decision, the swap, leftovers and
 * stop(). Nothing is downloaded from the network.
 */
import { createHash } from "node:crypto";
import { existsSync, mkdtempSync, readdirSync, readlinkSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { createMemoryLogger } from "../../src/log/index.js";
import { acceptedFileUrl, createIpnetdbLoader, IPNETDB_MAX_BYTES, shouldDownload, type IpnetdbLoader } from "../../src/shadow/ipnetdb.js";
import { buildMmdb, ipnetdbRecord } from "../helpers/mmdb-writer.js";

const MANIFEST_URL = "https://ipnetdb.example/latest.json";
const FILE_URL = "https://cdn.ipnetdb.net/ipnetdb_prefix_latest.mmdb";

function database(prefixEntity: string): Buffer {
  return buildMmdb({
    recordSize: 32,
    networks: [
      { network: "192.0.2.0/24", record: ipnetdbRecord({ prefix: "192.0.2.0/24", prefixEntity, asEntity: "Example Transit Inc", as: 64496 }) },
      { network: "203.0.113.0/25", record: ipnetdbRecord({ prefix: "203.0.113.0/25", prefixEntity: "Example Reserved", asEntity: "Example Reserved", as: 64497, bogon: true }) },
      { network: "2001:db8::/32", record: ipnetdbRecord({ prefix: "2001:db8::/32", prefixEntity, asEntity: "Example Transit Inc", as: 64498 }) },
    ],
  }).file;
}

const sha = (b: Buffer) => createHash("sha256").update(b).digest("hex");

interface Served {
  manifest: unknown;
  file: Buffer;
  manifestStatus?: number;
  fileStatus?: number;
  /** Never finish the file body (for stop during a download). */
  hangFile?: boolean;
}

function server(initial: Served) {
  const state = { ...initial };
  const calls: string[] = [];
  const fetchImpl = (async (input: RequestInfo | URL, init?: RequestInit) => {
    const url = String(input);
    calls.push(url);
    expect(init?.redirect).toBe("error");
    if (url === MANIFEST_URL) return new Response(JSON.stringify(state.manifest), { status: state.manifestStatus ?? 200 });
    if (state.hangFile) {
      const signal = init?.signal;
      const body = new ReadableStream<Uint8Array>({
        start(controller) {
          controller.enqueue(new Uint8Array(state.file.subarray(0, 1024)));
          signal?.addEventListener("abort", () => controller.error(new DOMException("aborted", "AbortError")));
        },
      });
      return new Response(body, { status: 200 });
    }
    return new Response(new Uint8Array(state.file), { status: state.fileStatus ?? 200 });
  }) as typeof fetch;
  return { state, calls, fetchImpl, fileCalls: () => calls.filter((c) => c !== MANIFEST_URL).length };
}

const manifestFor = (file: Buffer, date: string, overrides: Record<string, unknown> = {}) => ({
  prefix: { url: FILE_URL, file: "ipnetdb_prefix_latest.mmdb", date, sha256: sha(file), bytes: file.length, ...overrides },
  asn: { url: "https://cdn.ipnetdb.net/ipnetdb_asn_latest.mmdb", file: "ipnetdb_asn_latest.mmdb", date, sha256: "0".repeat(64), bytes: 1 },
});

/** File descriptors of this process that point into `dir` (Linux /proc); null where /proc is not available. */
function openFdsIn(dir: string): number | null {
  if (!existsSync("/proc/self/fd")) return null;
  let n = 0;
  for (const fd of readdirSync("/proc/self/fd")) {
    try {
      if (readlinkSync(`/proc/self/fd/${fd}`).startsWith(dir)) n += 1;
    } catch {
      /* closed meanwhile */
    }
  }
  return n;
}

let dir: string;
let loader: IpnetdbLoader | undefined;
// A Thursday: only the 7-day rule applies.
let today = new Date("2026-11-19T12:00:00Z");
beforeEach(() => {
  dir = join(mkdtempSync(join(tmpdir(), "ipnetdb-test-")), "db");
  today = new Date("2026-11-19T12:00:00Z");
});
afterEach(async () => {
  await loader?.stop();
  loader = undefined;
  rmSync(join(dir, ".."), { recursive: true, force: true });
});

function make(s: ReturnType<typeof server>, logger = createMemoryLogger(), maxBytes?: number) {
  loader = createIpnetdbLoader({ manifestUrl: MANIFEST_URL, dir, logger, fetchImpl: s.fetchImpl, now: () => today, ...(maxBytes ? { maxBytes } : {}) });
  return { loader, logger };
}

describe("IPNetDB loader", () => {
  it("answers unavailable until loaded, then serves found, not_found and bogon; logs date and bytes only", async () => {
    const file = database("Example Corp Ltd");
    const s = server({ manifest: manifestFor(file, "2026-11-19"), file });
    const { loader, logger } = make(s);
    expect(loader.lookup("192.0.2.10")).toEqual({ verdict: "unavailable" });
    expect(loader.loadedDate).toBeNull();
    expect(await loader.refresh()).toBe("loaded");
    expect(loader.loadedDate).toBe("2026-11-19");
    expect(loader.lookup("192.0.2.10")).toEqual({ verdict: "found", prefixEntity: "Example Corp Ltd", asEntity: "Example Transit Inc", asn: 64496 });
    expect(loader.lookup("2001:db8::1")).toMatchObject({ verdict: "found", asn: 64498 });
    expect(loader.lookup("198.51.100.1")).toEqual({ verdict: "not_found" });
    expect(loader.lookup("203.0.113.1")).toEqual({ verdict: "bogon" });
    expect(loader.lookup("not an address")).toEqual({ verdict: "unavailable" });
    const loaded = logger.entries.filter((e) => e["event"] === "ipnetdb_loaded");
    expect(loaded).toHaveLength(1);
    expect(loaded[0]).toMatchObject({ date: "2026-11-19", bytes: file.length });
    const text = JSON.stringify(logger.entries);
    for (const forbidden of ["ipnetdb.example", "cdn.ipnetdb.net", "Example Corp", dir]) expect(text).not.toContain(forbidden);
    // The file sits in IPNETDB_DIR under the loader's own name; no temporary file is left.
    expect(readdirSync(dir)).toEqual([`prefix-2026-11-19-${sha(file).slice(0, 12)}.mmdb`]);
  });

  it("a current copy is kept without downloading; a week newer manifest is downloaded and swapped in", async () => {
    const first = database("Example Corp Ltd");
    const s = server({ manifest: manifestFor(first, "2026-11-12"), file: first });
    const { loader } = make(s);
    expect(await loader.refresh()).toBe("loaded");
    expect(s.fileCalls()).toBe(1);
    expect(await loader.refresh()).toBe("current");
    // Six days newer on a Thursday: not yet.
    const second = database("Example Corp Two Ltd");
    s.state.manifest = manifestFor(second, "2026-11-18");
    s.state.file = second;
    expect(await loader.refresh()).toBe("current");
    expect(s.fileCalls()).toBe(1);
    // Seven days newer: download, swap, delete the old copy.
    s.state.manifest = manifestFor(second, "2026-11-19");
    expect(await loader.refresh()).toBe("loaded");
    expect(loader.loadedDate).toBe("2026-11-19");
    expect(loader.lookup("192.0.2.1")).toMatchObject({ prefixEntity: "Example Corp Two Ltd" });
    expect(readdirSync(dir)).toEqual([`prefix-2026-11-19-${sha(second).slice(0, 12)}.mmdb`]);
    expect(openFdsIn(dir) ?? 1).toBe(1);
  });

  it.each([
    ["sha256 mismatch", (f: Buffer) => ({ sha256: "f".repeat(64), bytes: f.length }), "sha_mismatch"],
    ["byte count mismatch", (f: Buffer) => ({ bytes: f.length + 1 }), "size_mismatch"],
    ["larger than the 400 MB bound", () => ({ bytes: IPNETDB_MAX_BYTES + 1 }), "too_large"],
    ["another host", () => ({ url: "https://downloads.example.org/ipnetdb_prefix_latest.mmdb" }), "host_refused"],
    ["plain http", () => ({ url: "http://cdn.ipnetdb.net/ipnetdb_prefix_latest.mmdb" }), "host_refused"],
  ])("%s: refused, the copy in use stays, nothing is left behind", async (_label, patch, category) => {
    const first = database("Example Corp Ltd");
    const s = server({ manifest: manifestFor(first, "2026-11-12"), file: first });
    const { loader, logger } = make(s);
    expect(await loader.refresh()).toBe("loaded");
    const second = database("Example Other Ltd");
    s.state.file = second;
    s.state.manifest = manifestFor(second, "2026-11-19", patch(second));
    const before = s.fileCalls();
    expect(await loader.refresh()).toBe("failed");
    expect(logger.entries.filter((e) => e["event"] === "ipnetdb_refresh_failed")).toEqual([expect.objectContaining({ category, level: "warn" })]);
    if (category === "too_large" || category === "host_refused") expect(s.fileCalls()).toBe(before);
    expect(loader.loadedDate).toBe("2026-11-12");
    expect(loader.lookup("192.0.2.1")).toMatchObject({ verdict: "found", prefixEntity: "Example Corp Ltd" });
    expect(readdirSync(dir)).toEqual([`prefix-2026-11-12-${sha(first).slice(0, 12)}.mmdb`]);
  });

  it("a file that is not a database is refused after verification and deleted", async () => {
    const junk = Buffer.from("not a database at all");
    const s = server({ manifest: manifestFor(junk, "2026-11-19"), file: junk });
    const { loader, logger } = make(s);
    expect(await loader.refresh()).toBe("failed");
    expect(logger.entries.find((e) => e["event"] === "ipnetdb_refresh_failed")).toMatchObject({ category: "invalid_file" });
    expect(loader.lookup("192.0.2.1")).toEqual({ verdict: "unavailable" });
    expect(readdirSync(dir)).toEqual([]);
  });

  it.each([
    ["manifest HTTP error", { manifestStatus: 503 }, "manifest_fetch"],
    ["manifest not in the expected format", { manifest: { prefix: { url: FILE_URL } } }, "manifest_invalid"],
    ["file HTTP error", { fileStatus: 404 }, "download"],
  ])("%s -> %s", async (_label, patch, category) => {
    const file = database("Example Corp Ltd");
    const s = server({ manifest: manifestFor(file, "2026-11-19"), file, ...patch });
    const { loader, logger } = make(s);
    expect(await loader.refresh()).toBe("failed");
    expect(logger.entries.find((e) => e["event"] === "ipnetdb_refresh_failed")).toMatchObject({ category });
    expect(loader.loadedDate).toBeNull();
  });

  it("removes its own leftovers from IPNETDB_DIR and nothing else", async () => {
    const file = database("Example Corp Ltd");
    const s = server({ manifest: manifestFor(file, "2026-11-19"), file });
    const { loader } = make(s);
    const { mkdirSync } = await import("node:fs");
    mkdirSync(dir, { recursive: true });
    writeFileSync(join(dir, ".prefix-2026-11-01-0123456789abcdef.part"), "partial");
    writeFileSync(join(dir, "prefix-2026-11-01-0123456789ab.mmdb"), "old copy");
    writeFileSync(join(dir, "someone-elses-file.txt"), "keep me");
    expect(await loader.refresh()).toBe("loaded");
    expect(readdirSync(dir).sort()).toEqual([`prefix-2026-11-19-${sha(file).slice(0, 12)}.mmdb`, "someone-elses-file.txt"]);
  });

  it("stop() closes the file, deletes it and answers unavailable; a stopped loader does nothing", async () => {
    const file = database("Example Corp Ltd");
    const s = server({ manifest: manifestFor(file, "2026-11-19"), file });
    const { loader } = make(s);
    await loader.refresh();
    expect(openFdsIn(dir) ?? 1).toBe(1);
    await loader.stop();
    expect(openFdsIn(dir) ?? 0).toBe(0);
    expect(loader.lookup("192.0.2.1")).toEqual({ verdict: "unavailable" });
    expect(readdirSync(dir)).toEqual([]);
    expect(await loader.refresh()).toBe("stopped");
  });

  it("stop() during a download aborts it and removes the temporary file", async () => {
    const file = database("Example Corp Ltd");
    const s = server({ manifest: manifestFor(file, "2026-11-19"), file, hangFile: true });
    const { loader, logger } = make(s);
    const run = loader.refresh();
    for (let i = 0; i < 100 && !(existsSync(dir) && readdirSync(dir).length > 0); i += 1) await new Promise((r) => setTimeout(r, 5));
    expect(await loader.refresh()).toBe("busy");
    await loader.stop();
    expect(await run).toBe("stopped");
    expect(readdirSync(dir)).toEqual([]);
    expect(logger.entries.some((e) => e["event"] === "ipnetdb_refresh_failed")).toBe(false);
  });

  it("start() loads in the background without blocking", async () => {
    const file = database("Example Corp Ltd");
    const s = server({ manifest: manifestFor(file, "2026-11-19"), file });
    const { loader } = make(s);
    loader.start();
    expect(loader.lookup("192.0.2.1")).toEqual({ verdict: "unavailable" });
    for (let i = 0; i < 200 && loader.loadedDate === null; i += 1) await new Promise((r) => setTimeout(r, 5));
    expect(loader.loadedDate).toBe("2026-11-19");
    loader.start();
    expect(s.calls.filter((c) => c === MANIFEST_URL)).toHaveLength(1);
  });
});

describe("refresh decision", () => {
  const thursday = new Date("2026-11-19T12:00:00Z");
  const monday = new Date("2026-11-23T08:00:00Z");
  it.each([
    [null, "2026-11-19", thursday, true],
    ["2026-11-19", "2026-11-19", thursday, false],
    ["2026-11-19", "2026-11-18", monday, false],
    ["2026-11-12", "2026-11-18", thursday, false],
    ["2026-11-12", "2026-11-19", thursday, true],
    ["2026-11-01", "2026-11-19", thursday, true],
    ["2026-11-19", "2026-11-22", monday, true],
    ["2026-11-22", "2026-11-23", monday, true],
    ["2026-11-23", "2026-11-23", monday, false],
  ])("loaded %s, manifest %s on %s -> %s", (loaded, manifest, now, expected) => {
    expect(shouldDownload(loaded, manifest, now)).toBe(expected);
  });

  it("accepts the file only over https from cdn.ipnetdb.net on the default port without credentials", () => {
    expect(acceptedFileUrl(FILE_URL)?.hostname).toBe("cdn.ipnetdb.net");
    const withCredentials = new URL(FILE_URL);
    withCredentials.username = "user";
    withCredentials.password = "pw";
    for (const bad of [
      "http://cdn.ipnetdb.net/x.mmdb",
      "https://cdn.ipnetdb.net.example.org/x.mmdb",
      "https://example.org/x.mmdb",
      "https://cdn.ipnetdb.net:8443/x.mmdb",
      withCredentials.toString(),
      "not a url",
    ]) {
      expect(acceptedFileUrl(bad), bad).toBeNull();
    }
  });
});
